def quick_sort(numbers):
    if len(numbers) <= 1:
        return numbers

    pivot = numbers[0]
    left = []
    equal = []
    right = []

    for number in numbers:
        if number < pivot:
            left.append(number)
        elif number == pivot:
            equal.append(number)
        else:
            right.append(number)

    return quick_sort(left) + equal + quick_sort(right)

print(quick_sort([3, 1, 2]))
